begin;
create extension if not exists pgtap with schema extensions;
select plan(8);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000007','retrieval@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000007','Retrieval');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000007','owner',now());
create temporary table ids(result jsonb);grant all on ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
insert into ids values(public.save_case_revision('20000000-0000-4000-8000-000000000007','{"title":"Canary","template":"product_delivery","outcome":"achieved","problem":"Canary","context":"Team","constraints":"No downtime","approach":"Canary","observedOutcome":"Released","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","sources":[],"conceptIds":[]}'));
select public.publish_case_revision((select (result->>'revisionId')::uuid from ids),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where workspace_id='20000000-0000-4000-8000-000000000007' and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);

create temporary table snapshots as select value as item from public.read_knowledge_case('20000000-0000-4000-8000-000000000007',(select (result->>'caseId')::uuid from ids),(select (result->>'revisionId')::uuid from ids),array['approach'],1) value;
create temporary table runs(result jsonb);
reset role;
with saved as (insert into public.analysis_runs(workspace_id,author_id,request_key,request,knowledge_version,deadline_at) values('20000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000007',gen_random_uuid(),'{"template":"product_delivery","version":1,"objective":"Release","context":"Team","hardConstraints":[],"conceptIds":[],"unknowns":""}',0,now()+interval '90 seconds') returning id) insert into runs select jsonb_build_object('runId',id) from saved;
set local role authenticated;
select throws_ok($$select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete','{"reusableApproach":[],"adjustments":[],"conflicts":[],"unknowns":[],"nextSteps":[]}',(select jsonb_build_array(jsonb_set(item,'{outcome}','"unknown"')) from snapshots),'',null)$$,'P0001','Invalid evidence','snapshot outcome cannot be forged');
select throws_ok($$select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete','{"reusableApproach":[{"kind":"observed","text":"Fact","references":[]}],"adjustments":[],"conflicts":[],"unknowns":[],"nextSteps":[]}',(select jsonb_agg(item) from snapshots),'',null)$$,'P0001','Missing citation','observed claim requires source');
select public.archive_case((select (result->>'caseId')::uuid from ids));
select public.finish_analysis((select (result->>'runId')::uuid from runs),'complete',jsonb_build_object('reusableApproach',jsonb_build_array(jsonb_build_object('kind','observed','text','The synthetic case used a canary.','references',jsonb_build_array((select jsonb_build_object('evidenceId',item->>'evidenceId','caseId',item->>'caseId','revisionId',item->>'revisionId','sectionKey',item->>'sectionKey') from snapshots)))),'adjustments','[]'::jsonb,'conflicts','[]'::jsonb,'unknowns','[]'::jsonb,'nextSteps',jsonb_build_array(jsonb_build_object('kind','proposal','text','Check applicability','references','[]'::jsonb))),(select jsonb_agg(item) from snapshots),'',null);
select is((select count(*) from public.briefs where workspace_id='20000000-0000-4000-8000-000000000007'),1::bigint,'authorized historical snapshot can be saved after archive');
select is((select events->-1->>'stage' from public.analysis_runs where id=(select (result->>'runId')::uuid from runs)),'completion','completion event is committed with terminal status');
select public.edit_brief((select id from public.briefs where workspace_id='20000000-0000-4000-8000-000000000007'),'User edit',true);
select is((select edited_text from public.briefs where workspace_id='20000000-0000-4000-8000-000000000007'),'User edit','user edit saved separately');
select is((select generated->'reusableApproach'->0->>'text' from public.briefs where workspace_id='20000000-0000-4000-8000-000000000007'),'The synthetic case used a canary.','generated brief unchanged by user edit');
reset role;
delete from public.workspace_members where workspace_id='20000000-0000-4000-8000-000000000007';
set local role authenticated;
select is((select count(*) from public.briefs),0::bigint,'revocation blocks historical brief snapshots');
select is((select count(*) from public.case_sections),0::bigint,'revocation blocks source excerpts');
select * from finish();rollback;
